content:
{
"code": ":root {
  --color-bg: #f3e8ff;
  --color-surface: #ffffff;
  --color-text-heading: #111827;
  --color-text-body: #374151;
  --color-text-muted: #6b7280;
  --color-accent-purple: #6b46c1;
  --color-accent-blue: #2563eb;
  --color-border: #e5e7eb;

  --font-sans: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, Roboto, 'Helvetica Neue', Arial, sans-serif;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-body);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.container {
  width: 100%;
  max-width: 430px;
  margin: 0 auto;
  padding: var(--space-lg) var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.page-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text-heading);
  margin: 0;
}

.search-wrapper {
  position: relative;
  width: 100%;
}

.search-wrapper input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  line-height: 1.5;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-surface);
  color: var(--color-text-body);
  outline: none;
}

.search-wrapper input::placeholder {
  color: var(--color-text-muted);
}

.category-chips {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-xs);
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.category-chips::-webkit-scrollbar {
  display: none;
}

.chip {
  flex-shrink: 0;
  padding: var(--space-xs) var(--space-sm);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  border: 1px solid var(--color-border);
  border-radius: 100px;
  background-color: var(--color-surface);
  color: var(--color-text-body);
  cursor: pointer;
  transition: all 0.2s ease;
}

.chip.active {
  background-color: var(--color-text-heading);
  color: var(--color-surface);
  border-color: var(--color-text-heading);
}

.mentor-grid {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.mentor-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.card-header {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.mentor-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  background-color: #f9fafb;
}

.mentor-info {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  min-width: 0;
  flex-grow: 1;
}

.mentor-name {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--color-text-heading);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mentor-role {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--color-text-muted);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.favorite-btn {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 0;
  transition: color 0.2s ease;
}

.favorite-btn:hover {
  color: #ef4444;
}

.favorite-btn svg {
  width: 20px;
  height: 20px;
}

.mentor-meta {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.badge {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
}

.badge.certification {
  background-color: rgba(107, 70, 193, 0.1);
  color: var(--color-accent-purple);
}

.badge.employer {
  background-color: rgba(37, 99, 235, 0.1);
  color: var(--color-accent-blue);
}

.mentor-desc {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-body);
  margin: 0;
  word-break: keep-all;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-sm);
  border-top: 1px solid var(--color-border);
  margin-top: var(--space-xs);
}

.fee-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-muted);
}

.action-btn {
  padding: var(--space-sm) var(--space-md);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  background-color: var(--color-text-heading);
  color: var(--color-surface);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.action-btn:hover:not(:disabled) {
  opacity: 0.9;
}

.action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.page-footer {
  font-size: 12px;
  color: var(--color-text-muted);
  text-align: center;
  margin-top: var(--space-md);
}"
}
